@extends('admin.layout') @section('title',$class->exists?'تعديل الصف':'إضافة صف') @section('content')<form class="form-card" method="post" action="{{ $class->exists?route('admin.classes.update',$class):route('admin.classes.store') }}">@csrf @if($class->exists)@method('put')@endif<div class="form-grid"><label>اسم الصف<input name="name" value="{{ old('name',$class->name) }}" required></label><label>المرحلة<input name="stage" value="{{ old('stage',$class->stage) }}" required></label><label>الشعبة<input name="section" value="{{ old('section',$class->section) }}"></label><label>السنة الدراسية<select name="academic_year_id" required>@foreach($years as $y)<option value="{{ $y->id }}" @selected(old('academic_year_id',$class->academic_year_id)==$y->id)>{{ $y->name }}</option>@endforeach</select></label><label class="wide">المواد<select multiple name="subject_ids[]">@foreach($subjects as $s)<option value="{{ $s->id }}" @selected(in_array($s->id,old('subject_ids',$class->subjects?->pluck('id')->all()??[])))>{{ $s->name }}</option>@endforeach</select></label></div>@if($class->exists && $students->isNotEmpty()) @php($selectedStudents=collect(old('student_ids',$class->students->pluck('id')->all())))<section class="panel" style="margin-top:18px"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><div><h2 style="margin:0">نقل طلبة إلى هذه الشعبة</h2><p class="muted" style="margin:.35rem 0 0">اختر أي مجموعة من طلبة الصف نفسه. الطلبة المحددون سينتقلون إلى هذه الشعبة عند الحفظ.</p></div><strong id="selected-students-count">{{ $selectedStudents->count() }} محدد</strong></div><div style="display:flex;gap:10px;margin:14px 0;flex-wrap:wrap"><input id="student-filter" type="search" placeholder="ابحث باسم الطالب أو رقمه" style="flex:1;min-width:220px"><button type="button" class="btn secondary" id="select-visible-students">تحديد الظاهر</button><button type="button" class="btn secondary" id="clear-visible-students">إلغاء تحديد الظاهر</button></div><div id="student-picker" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:8px;max-height:340px;overflow:auto">@foreach($students as $student)<label class="student-picker-option" data-search="{{ strtolower($student->user->name.' '.$student->student_number.' '.$student->classroom?->section) }}" style="display:flex;align-items:center;gap:8px;padding:9px;border:1px solid var(--line,#dbe7ea);border-radius:8px"><input type="checkbox" name="student_ids[]" value="{{ $student->id }}" @checked($selectedStudents->contains($student->id))><span><b>{{ $student->user->name }}</b><small style="display:block;color:#64748b">{{ $student->student_number }} · {{ $student->classroom?->section ?: 'بدون شعبة' }}</small></span></label>@endforeach</div></section>@elseif($class->exists)<p class="muted" style="margin-top:18px">لا يوجد طلبة آخرون في الصف نفسه يمكن نقلهم.</p>@endif<div class="form-actions"><button class="btn primary">حفظ</button></div></form>@push('scripts')<script>const picker=document.getElementById('student-picker');if(picker){const filter=document.getElementById('student-filter'),count=document.getElementById('selected-students-count'),options=[...picker.querySelectorAll('.student-picker-option')];const update=()=>{const q=filter.value.trim().toLowerCase();let n=0;options.forEach(o=>{o.style.display=!q||o.dataset.search.includes(q)?'flex':'none';if(o.querySelector('input').checked)n++});count.textContent=`${n} محدد`};document.getElementById('select-visible-students').onclick=()=>{options.forEach(o=>{if(o.style.display!=='none')o.querySelector('input').checked=true});update()};document.getElementById('clear-visible-students').onclick=()=>{options.forEach(o=>{if(o.style.display!=='none')o.querySelector('input').checked=false});update()};filter.oninput=update;picker.onchange=update;update()}</script>@endpush @endsection
